const renewMediaExecutor = `-- name: RenewMediaExecutor :execrows
UPDATE media_executor SET
 descriptor = CASE WHEN $1::bigint >= observed_at THEN $2 ELSE descriptor END,
 plan_quota = CASE WHEN $1::bigint >= observed_at AND $3::jsonb IS DISTINCT FROM quota_ref THEN NULL ELSE plan_quota END,
 quota_ref = CASE WHEN $1::bigint >= observed_at THEN $3 ELSE quota_ref END,
 readiness = CASE WHEN $1::bigint >= observed_at THEN $4 ELSE readiness END,
 max_concurrency = CASE WHEN $1::bigint >= observed_at THEN $5 ELSE max_concurrency END,
 observed_at = GREATEST($1::bigint, observed_at),
 connection_expires_at = now() + interval '90 seconds', updated_at = now()
WHERE workspace_id = $6 AND runtime_id = $7 AND daemon_id = $8
 AND executor_id = $9 AND credential_scope_id = $10
 AND provider = $11 AND capability = $12 AND connection_id = $13
 AND connection_expires_at > now()
`

type RenewMediaExecutorParams struct {
	ObservedAt        int64       `json:"observed_at"`
	Descriptor        []byte      `json:"descriptor"`
	QuotaRef          []byte      `json:"quota_ref"`
	Readiness         string      `json:"readiness"`
	MaxConcurrency    int32       `json:"max_concurrency"`
	WorkspaceID       pgtype.UUID `json:"workspace_id"`
	RuntimeID         pgtype.UUID `json:"runtime_id"`
	DaemonID          string      `json:"daemon_id"`
	ExecutorID        pgtype.UUID `json:"executor_id"`
	CredentialScopeID pgtype.UUID `json:"credential_scope_id"`
	Provider          string      `json:"provider"`
	Capability        string      `json:"capability"`
	ConnectionID      pgtype.UUID `json:"connection_id"`
}

// Heartbeats cannot register a new executor or take over another connection.
func (q *Queries) RenewMediaExecutor(ctx context.Context, arg RenewMediaExecutorParams) (int64, error) {
	result, err := q.db.Exec(ctx, renewMediaExecutor,
		arg.ObservedAt,
		arg.Descriptor,
		arg.QuotaRef,
		arg.Readiness,
		arg.MaxConcurrency,
		arg.WorkspaceID,
		arg.RuntimeID,
		arg.DaemonID,
		arg.ExecutorID,
		arg.CredentialScopeID,
		arg.Provider,
		arg.Capability,
		arg.ConnectionID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

